"""CRUD endpoints for organizers."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Organizer
from app.schemas import OrganizerCreate, OrganizerRead, OrganizerUpdate

router = APIRouter(prefix="/organizers", tags=["organizers"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, organizer_id: int) -> Organizer:
    organizer = session.get(Organizer, organizer_id)
    if organizer is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Organizer not found")
    return organizer


@router.get("", response_model=list[OrganizerRead])
def list_organizers(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Organizer]:
    query = select(Organizer).order_by(Organizer.id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=OrganizerRead, status_code=status.HTTP_201_CREATED)
def create_organizer(payload: OrganizerCreate, session: SessionDep) -> Organizer:
    organizer = Organizer(**payload.model_dump())
    session.add(organizer)
    session.commit()
    session.refresh(organizer)
    return organizer


@router.get("/{organizer_id}", response_model=OrganizerRead)
def get_organizer(organizer_id: int, session: SessionDep) -> Organizer:
    return _get_or_404(session, organizer_id)


@router.patch("/{organizer_id}", response_model=OrganizerRead)
def update_organizer(
    organizer_id: int,
    payload: OrganizerUpdate,
    session: SessionDep,
) -> Organizer:
    organizer = _get_or_404(session, organizer_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(organizer, key, value)
    session.commit()
    session.refresh(organizer)
    return organizer


@router.delete("/{organizer_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_organizer(organizer_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, organizer_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

"""CRUD endpoints for events."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Event, Organizer
from app.schemas import EventCreate, EventRead, EventUpdate

router = APIRouter(prefix="/events", tags=["events"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, event_id: int) -> Event:
    event = session.get(Event, event_id)
    if event is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Event not found")
    return event


def _check_parents(
    session: Session,
    organizer_id: int | None,
) -> None:
    """An event must point at an organizer that exist."""
    if organizer_id is not None and session.get(Organizer, organizer_id) is None:
        raise HTTPException(422, detail=f"Organizer {organizer_id} not found")


@router.get("", response_model=list[EventRead])
def list_events(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
    organizer_id: Annotated[int | None, Query(gt=0)] = None,
) -> list[Event]:
    query = select(Event).order_by(Event.id)
    if organizer_id is not None:
        query = query.where(Event.organizer_id == organizer_id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=EventRead, status_code=status.HTTP_201_CREATED)
def create_event(payload: EventCreate, session: SessionDep) -> Event:
    _check_parents(session, payload.organizer_id)
    event = Event(**payload.model_dump())
    session.add(event)
    session.commit()
    session.refresh(event)
    return event


@router.get("/{event_id}", response_model=EventRead)
def get_event(event_id: int, session: SessionDep) -> Event:
    return _get_or_404(session, event_id)


@router.patch("/{event_id}", response_model=EventRead)
def update_event(
    event_id: int,
    payload: EventUpdate,
    session: SessionDep,
) -> Event:
    event = _get_or_404(session, event_id)
    _check_parents(session, payload.organizer_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(event, key, value)
    session.commit()
    session.refresh(event)
    return event


@router.delete("/{event_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_event(event_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, event_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

