"""CRUD endpoints for tickets."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Attendee, Event, Ticket
from app.schemas import TicketCreate, TicketRead, TicketUpdate

router = APIRouter(prefix="/tickets", tags=["tickets"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, ticket_id: int) -> Ticket:
    ticket = session.get(Ticket, ticket_id)
    if ticket is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Ticket not found")
    return ticket


def _check_parents(
    session: Session,
    event_id: int | None,
    attendee_id: int | None,
) -> None:
    """A ticket must point at an event and an attendee that exist."""
    if event_id is not None and session.get(Event, event_id) is None:
        raise HTTPException(422, detail=f"Event {event_id} not found")
    if attendee_id is not None and session.get(Attendee, attendee_id) is None:
        raise HTTPException(422, detail=f"Attendee {attendee_id} not found")


@router.get("", response_model=list[TicketRead])
def list_tickets(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
    event_id: Annotated[int | None, Query(gt=0)] = None,
    attendee_id: Annotated[int | None, Query(gt=0)] = None,
) -> list[Ticket]:
    query = select(Ticket).order_by(Ticket.id)
    if event_id is not None:
        query = query.where(Ticket.event_id == event_id)
    if attendee_id is not None:
        query = query.where(Ticket.attendee_id == attendee_id)
    return list(session.scalars(query.offset(offset).limit(limit)))


@router.post("", response_model=TicketRead, status_code=status.HTTP_201_CREATED)
def create_ticket(payload: TicketCreate, session: SessionDep) -> Ticket:
    _check_parents(session, payload.event_id, payload.attendee_id)
    ticket = Ticket(**payload.model_dump())
    session.add(ticket)
    session.commit()
    session.refresh(ticket)
    return ticket


@router.get("/{ticket_id}", response_model=TicketRead)
def get_ticket(ticket_id: int, session: SessionDep) -> Ticket:
    return _get_or_404(session, ticket_id)


@router.patch("/{ticket_id}", response_model=TicketRead)
def update_ticket(
    ticket_id: int,
